import torch


def run(grad_output, input, padding):
    return torch.ops.aten.reflection_pad1d_backward(grad_output, input, padding)


def gen_inputs(ctx, device):
    shape = ctx["grad_output__shape"]
    dtype = ctx["grad_output__dtype"]
    if isinstance(dtype, str):
        dtype = getattr(torch, dtype)
    return {"grad_output": torch.ones(shape, dtype=dtype, device=device)}
